def _predict(a, b, kernel, cross_kernel, target, regularization):
    w = np.linalg.solve(kernel + regularization * np.eye(len(a)), np.column_stack((a, target)))
    (wa, wy) = (w[:, :a.shape[1]], w[:, a.shape[1]:])
    trend = np.linalg.solve(a.T @ wa, a.T @ wy)
    return b @ trend + cross_kernel @ (wy - wa @ trend)

def _poly(x, degrees):
    from itertools import combinations_with_replacement
    return np.column_stack([np.prod(x[:, js], axis=1) for k in degrees for js in combinations_with_replacement(range(4), k)])

def _dictionary(d, z, w):
    from itertools import combinations
    blocks = [d, z, w, _poly(d, [2]), _poly(d, [3])]
    for (idx, f) in enumerate([d, z, w, z + w, z - w, d + z, d + w, z * w]):
        if idx < 3:
            f = np.column_stack([f] + [f[:, i] + sg * f[:, j] for (i, j) in combinations(range(4), 2) for sg in [-1, 1]])
        for k in [0.5, 1, 1.7, 2.5]:
            blocks.extend([np.sin(k * f), np.cos(k * f) - 1, np.tanh(k * f), f / (1 + k * abs(f)), f / (1 + k * f * f), f * f / (1 + k * f * f)])
